#!/usr/bin/env python3
"""The World Today — Tuesday 17 November 2026, 20 stories.

make.fun bounty entry: news-image-20261117
("Sum up 17 November's world news in one image", $250).

Concept: a dense newspaper front page, the format the judge has
rewarded before — a big date masthead, one lead story, twenty
numbered stories, a world map, a markets box and a sources line,
all legible in a single image.

The front page "THE WORLD TODAY — TUESDAY 17 NOVEMBER 2026"
carries these 20 stories:

 1. Russia hits two Kyiv bridges (missiles strike two Dnipro crossings)
 2. Tankers hit by mines near Hormuz (two oil tankers struck and ablaze)
 3. Iran fires drones at US radar in Bahrain
 4. Trump lands in Manila for ASEAN; Xi-Trump-Putin talks set for Thursday
 5. JPMorgan blames software bug for outage (online banking and Zelle slowed)
 6. Nvidia reports first earnings since Huang exit
 7. Vulcan rocket fails, 40 Amazon satellites lost
 8. Five EU states plan Rwanda migrant hub
 9. Estonia to shut Russia border crossings from 1 December
10. Microsoft explains global outage (80 percent of servers knocked out)
11. House Democrats outline opening agenda
12. Houthis target Saudi oil pipeline
13. Iraq sends army into militia stronghold (Kataib Hezbollah base)
14. Singapore seeks trusted AI chip access amid US export curbs
15. Japan scrambles jets over Russian flights
16. US petrol falls to $3.78 a gallon
17. WHO: Eritrea eliminates trachoma
18. Bus plunge kills six in Uttarakhand
19. Sri Lanka bowled out for 98
20. Broncos open as 10-point favourites over the Raiders

Plus a "WHERE IT HAPPENED" world map, an INDEX (BY LOCATION) box, a
MARKETS box and a sources footer (BBC, Reuters, Al Jazeera, AP, NPR).

Image facts: 1024 x 1024 JPEG, 497,944 bytes, embedded below as a
single base64 string. The script writes those exact bytes to
$MAKEFUN_OUTPUT_DIR/entry.png (default /output). No network, no
randomness, no model calls — two runs write identical bytes.
"""

import base64
import hashlib
import os
import sys

# The front-page image, base64-encoded JPEG (1024x1024, 497,944 bytes).
DATA = ""


def main() -> int:
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    raw = base64.b64decode(DATA)
    path = os.path.join(out_dir, "entry.png")
    with open(path, "wb") as f:
        f.write(raw)
    sha = hashlib.sha256(raw).hexdigest()
    print(f"wrote {path} ({len(raw)} bytes, sha256 {sha})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
